# shellcheck shell=bash disable=SC2034
# Monitor layout for host desktop (generated by install.sh).
# Edit this file or re-run: ./install.sh --monitors
#
# MON_NAME     output name (hyprctl monitors)
# MON_MODE     resolution@refresh, or "preferred"
# MON_POSITION global position, or "auto"
# MON_SCALE    fractional scale, e.g. "1" or "1.25"
# MON_WS_FIRST first workspace number on this monitor
# MON_WS_COUNT how many workspace slots this monitor owns

# No preset: Hyprland uses the connected outputs. Run ./install.sh --monitors
# to record an explicit layout with per-monitor workspace ranges.
MON_COUNT=0

# App workspaces follow the monitor count: 12/13 with a second monitor,
# 6/7 on a single one (computed by install.sh).
